<?php use App\Support\App;$u=App::requireAuth();$gs=App::db()->query('SELECT code,name FROM payment_gateways WHERE is_active=1')->fetchAll();$title='Deposit';require __DIR__.'/../layouts/head.php';?><div class="flex"><?php require __DIR__.'/../components/sidebar.php';?><main class="p-8 flex-1"><h1 class="text-2xl font-semibold">Deposit</h1><form id="d" class="saas-card p-6 mt-6 max-w-xl space-y-4"><input type="hidden" id="csrf" value="<?=App::csrf()?>"><input class="field" name="amount" type="number" min="1000" required><select class="field" name="gateway"><?php foreach($gs as $g):?><option value="<?=$g['code']?>"><?=htmlspecialchars($g['name'])?></option><?php endforeach?></select><button class="btn btn-dark">Create deposit</button></form></main></div><script>d.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/deposits',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},body:JSON.stringify(Object.fromEntries(new FormData(d)))});Swal.fire(JSON.stringify(await r.json()))}</script><?php require __DIR__.'/../layouts/foot.php';?>